m_opencode_sessionMessageEnvelope.signature:
type sessionMessageEnvelope struct {
	Info	struct {
		ID	string	`json:"id"`
		Role	string	`json:"role"`
		Time	struct {
			Completed int64 `json:"completed"`
		}	`json:"time"`
		Finish	string		`json:"finish"`
		Error	json.RawMessage	`json:"error"`
	}	`json:"info"`
	Parts	[]struct {
		Type	string	`json:"type"`
		Text	string	`json:"text"`
		// State 是 tool part 的运行时状态（state.status 区分 running/completed/error）；
		// 非 tool part 无此字段。Error 是失败时服务端写入的原文——权限被拒时是
		// 固定哨兵文案（见 reconcile.go rejectedToolSentinel），对账归因靠它
		State	struct {
			Status string `json:"status"`
			Error string `json:"error"`
		}	`json:"state"`
	}	`json:"parts"`
}

